import org.daidai.modules.music.WaveWriter;
import org.daidai.modules.music.WavSpeedProcessor;
import org.daidai.modules.music.StereoPcmReader;
import java.io.*;

public final class WavSpeedChecks {
    private static int checks;
    private static void test(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    private static int intLE(RandomAccessFile in)throws Exception{return in.readUnsignedByte()|in.readUnsignedByte()<<8|in.readUnsignedByte()<<16|in.readUnsignedByte()<<24;}
    private static double[] inspect(File file)throws Exception{try(RandomAccessFile in=new RandomAccessFile(file,"r")){in.seek(22);int channels=in.readUnsignedByte()|in.readUnsignedByte()<<8;int rate=intLE(in);in.seek(40);int size=intLE(in);int frames=size/(channels*2);in.seek(44);int crossings=0;short old=0;for(int i=0;i<frames;i++){short v=(short)(in.readUnsignedByte()|in.readByte()<<8);for(int c=1;c<channels;c++)in.skipBytes(2);if(i>frames/5&&i<frames*4/5&&old<=0&&v>0)crossings++;old=v;}return new double[]{frames/(double)rate,crossings/((frames*3/5)/(double)rate)};}}
    private static void readerChecks(File root)throws Exception{File stereo=File.createTempFile("stereo-reader-",".wav",root),mono=File.createTempFile("mono-reader-",".wav",root);try{try(WaveWriter w=new WaveWriter(stereo,1000,2)){for(int i=0;i<100;i++){w.sample((short)(i*100));w.sample((short)(-i*100));}}try(StereoPcmReader r=new StereoPcmReader(stereo)){float[][] p=r.read(10,8);test(r.channels()==2&&r.frames()==100&&r.sampleRate()==1000,"PCM stereo header");test(Math.abs(p[0][0]-1000/32768f)<.00001&&Math.abs(p[1][0]+1000/32768f)<.00001,"PCM independent left right at position");test(r.read(1000,8)[0][0]==0,"PCM end window zero fill");}try(WaveWriter w=new WaveWriter(mono,1000,1)){w.sample((short)-12345);}try(StereoPcmReader r=new StereoPcmReader(mono)){float[][] p=r.read(0,8);test(p[0][0]==p[1][0]&&p[0][0]<0,"mono duplicates to both XY axes");}try(RandomAccessFile f=new RandomAccessFile(stereo,"rw")){f.setLength(50);}boolean rejected=false;try{new StereoPcmReader(stereo).close();}catch(IOException e){rejected=true;}test(rejected,"truncated PCM rejected");}finally{stereo.delete();mono.delete();}}
    public static void main(String[] args)throws Exception{File root=new File(args.length>0?args[0]:System.getProperty("java.io.tmpdir"));root.mkdirs();readerChecks(root);File source=File.createTempFile("speed-in-",".wav",root),shift=File.createTempFile("speed-shift-",".wav",root),preserved=File.createTempFile("speed-keep-",".wav",root),cancel=File.createTempFile("speed-cancel-",".wav",root);try{try(WaveWriter w=new WaveWriter(source,44100,2)){for(int i=0;i<88200;i++){short v=(short)Math.round(Math.sin(i*2*Math.PI*440/44100)*18000);w.sample(v);w.sample(v);}}WavSpeedProcessor.process(source,shift,1.5f,false);WavSpeedProcessor.process(source,preserved,1.5f,true);double[] changed=inspect(shift),kept=inspect(preserved);test(Math.abs(changed[0]-2/1.5)<.002,"shift duration");test(Math.abs(changed[1]-660)<5,"shift frequency");test(Math.abs(kept[0]-2/1.5)<.002,"preserved duration");test(Math.abs(kept[1]-440)<10,"preserved frequency "+kept[1]);Thread.currentThread().interrupt();try{WavSpeedProcessor.process(source,cancel,1.5f,true);throw new AssertionError("cancel missing");}catch(InterruptedException expected){test(!cancel.exists(),"cancel output removed");}finally{Thread.interrupted();}System.out.println("PASS: "+checks+" WAV speed checks (duration, pitch, cancellation)");}finally{source.delete();shift.delete();preserved.delete();cancel.delete();}}
}
